mapper.select:


    b.del_flag = '0'

        and b.batch_no like concat('%', #{batchNo}, '%')


        and b.stat_month = #{statMonth}


        and b.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and b.batch_status = #{batchStatus}


        and b.account_status = #{accountStatus}


        and b.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}

order by b.stat_month desc, b.batch_id desc
